import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    heights = data[1:1 + n]

    max_height = 0
    visible = 0

    for h in reversed(heights):
        if h > max_height:
            visible += 1
            max_height = h

    print(n - visible)

if __name__ == "__main__":
    main()
